import three; defaultpen(linewidth(1)); currentprojection = orthographic(0,-3,0.5); pen dots = linetype("0 3") + linewidth(1);
real h = 2.3, ratio = (91-24)/(171-24);
picture p1, p2; /* p1 is left-hand picture */
